      projectRepo.listProjects({ orgId, limit: PAGE_SIZE, cursor }),
    )) {
      live.add(`project:${project.id}`);
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }

    // Archived issues are not searchable, and neither are their comments:
    // only live issues are walked, and only their live comments (replies
    // included, whatever became of the parent) are indexed.
    for await (const issue of walkPages((cursor) =>
      issueRepo.listIssues({ orgId, limit: PAGE_SIZE, cursor }),
    )) {
      live.add(`issue:${issue.id}`);
      try {
        await indexIssue(orgId, issue);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index issue", {
          issueId: issue.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }

      try {
        for await (const comment of walkPages((cursor) =>
          commentRepo.listLiveCommentsForIssue(
            orgId,
            issue.id,
            PAGE_SIZE,
            cursor,
          ),
        )) {
          live.add(`comment:${comment.id}`);
          try {
            await indexComment(orgId, comment);
            result.processed += 1;
          } catch (error) {
            result.failed += 1;
            logger.error("failed to index comment", {
              commentId: comment.id,
              reason: error instanceof Error ? error.message : String(error),
            });
