import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import * as searchRepo from "@/server/repositories/search-repository";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("tmp", () => {
  it("works", async () => {
    const detach = searchService.registerSearchListeners();
    const t = await createTenant("tmpreidx", "growth");
    const other = await createTenant("tmpother", "growth");
    const a = t.actors.member;
    const issues = [];
    for (let i = 0; i < 130; i++) issues.push(await issueService.createIssue(a, issueInput(t.org.id, t.project.id, { title: `Iss ${i}` })));
    const mk = (issueId: any, body: string, parentId: any = null) => commentService.createComment(a, { orgId: t.org.id, issueId, body, parentId, mentionedUserIds: [] });
    const i0 = issues[0]!;
    const cs = [];
    for (let i = 0; i < 120; i++) cs.push(await mk(i0.id, `cmt ${i}`));
    const parent = await mk(i0.id, "parentx");
    const reply = await mk(i0.id, "replyx", parent.id);
    await commentService.deleteComment(a, { orgId: t.org.id, commentId: parent.id });
    await commentService.deleteComment(a, { orgId: t.org.id, commentId: cs[5]!.id });
    expect((await searchService.search(a, { orgId: t.org.id, q: "parentx", kinds: [], limit: 25, cursor: null })).total).toBe(0);
    expect((await searchService.search(a, { orgId: t.org.id, q: "replyx", kinds: [], limit: 25, cursor: null })).total).toBe(1);
    expect((await issueService.getIssue(a, t.org.id, i0.id)).commentCount).toBe(120);
    const i1 = issues[1]!;
    await mk(i1.id, "archivedcmt");
    await issueService.archiveIssue(a, t.org.id, i1.id);
    expect((await searchService.search(a, { orgId: t.org.id, q: "archivedcmt", kinds: [], limit: 25, cursor: null })).total).toBe(0);
    const before = await searchRepo.countIndexed(t.org.id);
    const oc = await issueService.createIssue(other.actors.member, issueInput(other.org.id, other.project.id, { title: "otherorg" }));
    const oBefore = await searchRepo.countIndexed(other.org.id);
    await runSearchReindexJob(t.org.id);
    const after1 = await searchRepo.countIndexed(t.org.id);
    await runSearchReindexJob(t.org.id);
    expect(await searchRepo.countIndexed(t.org.id)).toBe(after1);
    // project + 129 live issues + 119 live cmts on i0 (120 + reply - 1 deleted) - wait: 120-1 + reply
    expect(after1).toBe(1 + 129 + 119 + 1);
    expect(await searchRepo.countIndexed(other.org.id)).toBe(oBefore);
    for (const q of ["parentx", "archivedcmt", "cmt 5 "]) expect((await searchService.search(a, { orgId: t.org.id, q, kinds: [], limit: 25, cursor: null })).total).toBe(0);
    expect((await searchService.search(a, { orgId: t.org.id, q: "Iss 0", kinds: ["issue"], limit: 25, cursor: null })).total).toBeGreaterThan(0);
    console.log(before, after1);
    detach();
  });
});
EOF
